const body = $('Publish Trigger Webhook').first().json.body;
const contract = $json.contract;
const errors = [];

const requestId = body.request_id;
const actor = body.actor;
const buildChecksum = body.build_checksum;
const targetEnvironment = body.target_environment;
const expiry = body.expiry;

if (!actor) errors.push('actor is required');
if (!buildChecksum) errors.push('build_checksum is required');
if (!targetEnvironment) errors.push('target_environment is required');
if (!expiry) errors.push('expiry is required');

const expiryDate = expiry ? new Date(expiry) : null;
if (expiry && (Number.isNaN(expiryDate?.getTime()) || expiryDate.getTime() <= Date.now())) {
  errors.push('expiry is malformed or already in the past');
}

const currentChecksum = contract.stage_artifacts && contract.stage_artifacts.build_checksum;
if (buildChecksum && currentChecksum && buildChecksum !== currentChecksum) {
  errors.push('build_checksum does not match the latest reviewed build (' + currentChecksum + ') -- stale or forged approval');
}
if (!currentChecksum) errors.push('no reviewed build_checksum exists yet on this contract');

return [{ json: { valid: errors.length === 0, errors, request_id: requestId, actor, build_checksum: buildChecksum, target_environment: targetEnvironment, expiry, contract } }];

// v1 default adapter -- see publication-policy.json 'production_adapter' and
// automation/README.md for the swap contract. Replace this node's code to
// deploy to real hosting once the mechanism is known; input/output shape
// documented there must be preserved.
const ctx = $('Validate Approval Fields').first().json;
const manifest = (ctx.contract.stage_artifacts && ctx.contract.stage_artifacts.build_manifest) || [];
const adapterResult = {
  ok: true,
  adapter: 'staging-passthrough',
  published_base_url: 'http://wp-staging',
  published_at: new Date().toISOString(),
  note: 'v1 default adapter: staging IS the artifact of record; replace this node to deploy to real hosting.',
};
return [{ json: { request_id: ctx.request_id, manifest, adapter_result: adapterResult } }];

const ctx = $json;
return ctx.manifest.map(m => ({ json: {
  request_id: ctx.request_id,
  artifact_key: m.artifact_key,
  expected_post_id: m.post_id,
  mcp_request: {
    jsonrpc: '2.0',
    id: ctx.request_id + ':smoke:' + m.artifact_key,
    method: 'tools/call',
    params: { name: 'get_post', arguments: { post_id: m.post_id } }
  }
} }));

const results = $input.all().map((item, idx) => {
  const expected = $('Build Smoke Check Items').all()[idx].json;
  let live = null;
  let available = false;
  try {
    live = JSON.parse(item.json.result.content[0].text);
    available = live && live.ID === expected.expected_post_id;
  } catch (e) {
    live = { error: 'unparseable smoke-check response' };
  }
  return { artifact_key: expected.artifact_key, post_id: expected.expected_post_id, available, live_status: live && live.status };
});

const manifestCount = $('Build Smoke Check Items').all().length;
const availableCount = results.filter(r => r.available).length;
const pageCountMatches = availableCount === manifestCount;
const allAvailable = results.every(r => r.available);
const smokePass = pageCountMatches && allAvailable;

const notAutomatedV1 = ['navigation_path', 'form_submission_path', 'indexing_state', 'visual_regression'];

return [{ json: {
  request_id: $('Invoke Production Adapter').first().json.request_id,
  smoke_pass: smokePass,
  checks: { availability: allAvailable, page_count_matches_manifest: pageCountMatches, manifest_readback: results },
  not_automated_v1: notAutomatedV1,
  adapter_result: $('Invoke Production Adapter').first().json.adapter_result,
} }];
